// ─────────────────────────────────────────────────────────────────────────────
// CAPTURE — shared contract. Every module codes against this file.
// DO NOT edit this file from a system module; use the `ext` bags for extra state.
// ─────────────────────────────────────────────────────────────────────────────

/** Simulation runs at a fixed 10 ticks per second (at 1x speed). */
export const TICK_MS = 100;
export const TICKS_PER_SEC = 10;

/** A tile index: i = y * W + x. */
export type Tile = number;
/** Player id. 0 = nobody (unclaimed land, or water). Real players start at 1. */
export type PlayerId = number;

// Terrain codes stored in MapData.terrain / Game.terrain
export const WATER = 0;
export const PLAINS = 1;
export const HILLS = 2;
export const MOUNTAIN = 3;

/** Share of all land tiles a single player must own to win. */
export const WIN_SHARE = 0.8;

export interface NationSeed {
  name: string;
  /** Spawn position in tile coords (should be on land; the core snaps to nearest land). */
  x: number;
  y: number;
  /** 0..1 relative importance (big countries ≈ 1). Used to pick which nations spawn first. */
  strength: number;
}

export interface MapData {
  name: string;
  width: number;
  height: number;
  /** width*height terrain codes (WATER/PLAINS/HILLS/MOUNTAIN). */
  terrain: Uint8Array;
  nations: NationSeed[];
}

export type PlayerKind = 'human' | 'nation' | 'tribe';
export type Difficulty = 'easy' | 'normal' | 'hard';

export interface Player {
  id: PlayerId;
  name: string;
  kind: PlayerKind;
  /** 0xRRGGBB */
  color: number;
  alive: boolean;
  troops: number;
  gold: number;
  /** Number of owned tiles — maintained by Game.setOwner. */
  tiles: number;
  /** Sum of x / y of owned tiles (centroid = sumX/tiles) — maintained by Game.setOwner. */
  sumX: number;
  sumY: number;
  /** Owned tiles with at least one 4-neighbour of a different owner (coast counts) — maintained by Game.setOwner. */
  border: Set<Tile>;
  spawnX: number;
  spawnY: number;
  allies: Set<PlayerId>;
  /** Players this player refuses to trade with. */
  embargoes: Set<PlayerId>;
  /** Tick until which this player is flagged as traitor (broke an alliance). 0 = never. */
  traitorUntil: number;
  /** Free-form per-system state (AI memory, cooldowns…). Namespaced by system, e.g. ext.ai. */
  ext: Record<string, any>;
}

export type StructureType = 'city' | 'port' | 'fort' | 'factory' | 'silo' | 'sam';
export const STRUCTURE_TYPES: StructureType[] = ['city', 'port', 'fort', 'factory', 'silo', 'sam'];

export interface Structure {
  id: number;
  type: StructureType;
  owner: PlayerId;
  tile: Tile;
  x: number;
  y: number;
  builtTick: number;
  /** Under construction (inactive) until game.tick >= readyTick. */
  readyTick: number;
  /** Reload: silo/sam cannot fire until game.tick >= cooldownUntil. */
  cooldownUntil: number;
  ext: Record<string, any>;
}

export type UnitType = 'transport' | 'trade' | 'atom' | 'hydrogen' | 'interceptor';

export interface Unit {
  id: number;
  type: UnitType;
  owner: PlayerId;
  /** Current position in (fractional) tile coords. */
  x: number;
  y: number;
  fromTile: Tile;
  toTile: Tile;
  /** Troops carried (transport), else 0. */
  troops: number;
  alive: boolean;
  ext: Record<string, any>;
}

export type NukeKind = 'atom' | 'hydrogen';

export interface Attack {
  id: number;
  attacker: PlayerId;
  /** 0 = unclaimed land. */
  target: PlayerId;
  /** Troops still committed to this attack. */
  troops: number;
  startTroops: number;
  alive: boolean;
  ext: Record<string, any>;
}

export interface AllianceRequest {
  id: number;
  from: PlayerId;
  to: PlayerId;
  tick: number;
}

export type MsgLevel = 'info' | 'good' | 'warn' | 'danger';

export type GameEvent =
  /** Log line. `to` undefined = visible to everybody. Text is Italian. Optional map position to jump to. */
  | { type: 'message'; text: string; level: MsgLevel; to?: PlayerId; x?: number; y?: number }
  | { type: 'playerDied'; id: PlayerId; by: PlayerId }
  | { type: 'win'; id: PlayerId }
  | { type: 'allianceRequest'; request: AllianceRequest }
  | { type: 'allianceFormed'; a: PlayerId; b: PlayerId }
  | { type: 'allianceBroken'; by: PlayerId; other: PlayerId; betrayal: boolean }
  | { type: 'structureBuilt'; structure: Structure }
  | { type: 'structureCaptured'; structure: Structure; previousOwner: PlayerId }
  | { type: 'structureDestroyed'; structure: Structure }
  | { type: 'nukeLaunched'; unit: Unit }
  | { type: 'nukeIntercepted'; x: number; y: number; owner: PlayerId }
  /** `victims` = players (other than nobody) that lost tiles in the blast. */
  | { type: 'explosion'; x: number; y: number; radius: number; kind: NukeKind; owner: PlayerId; victims: PlayerId[] }
  /** Emitted by attacks.ts when a NEW attack is created (not on reinforcement). */
  | { type: 'attackStarted'; attack: Attack }
  | { type: 'boatLaunched'; unit: Unit }
  | { type: 'boatLanded'; owner: PlayerId; tile: Tile; troops: number };

export interface System {
  name: string;
  tick(): void;
}

/**
 * Commands — the ONLY way UI and AI change the game. Each returns true if accepted.
 * Default implementations are no-op stubs returning false; systems overwrite them in install*().
 */
export interface Commands {
  /** Land attack. Needs a shared land border (target 0 = unclaimed land). Reinforces an existing attack on the same target. [attacks.ts] */
  attack(attacker: PlayerId, target: PlayerId, troops: number): boolean;
  /** Call back an attack; surviving troops return home (minus a penalty). [attacks.ts] */
  retreat(attackId: number): boolean;
  /** [buildings.ts] */
  build(player: PlayerId, type: StructureType, tile: Tile): boolean;
  /** Amphibious assault: troops sail from the player's coast to (the coast nearest to) targetTile, then attack its owner. [naval.ts] */
  sendBoat(player: PlayerId, targetTile: Tile, troops: number): boolean;
  /** [nukes.ts] */
  launchNuke(player: PlayerId, kind: NukeKind, targetTile: Tile): boolean;
  /** [diplomacy.ts] */
  proposeAlliance(from: PlayerId, to: PlayerId): boolean;
  respondAlliance(requestId: number, accept: boolean): boolean;
  breakAlliance(by: PlayerId, other: PlayerId): boolean;
  setEmbargo(by: PlayerId, other: PlayerId, on: boolean): boolean;
  donate(from: PlayerId, to: PlayerId, kind: 'troops' | 'gold', amount: number): boolean;
}

/** Read-only queries used by UI and AI. Stubs return neutral values until the owning system installs. */
export interface Queries {
  /** Troop cap. [economy.ts] */
  maxTroops(p: PlayerId): number;
  /** Troops gained per tick right now. [economy.ts] */
  troopRate(p: PlayerId): number;
  /** Gold gained per tick right now. [economy.ts] */
  goldRate(p: PlayerId): number;
  /** Gold price of the next structure of this type for this player. [buildings.ts] */
  buildCost(p: PlayerId, type: StructureType): number;
  /** null = allowed, otherwise a short Italian reason. [buildings.ts] */
  canBuild(p: PlayerId, type: StructureType, tile: Tile): string | null;
  /** Defence multiplier (>= 1) of a tile: terrain, forts in range, etc. [attacks.ts] */
  defenseAt(tile: Tile): number;
  /** null = allowed, otherwise a short Italian reason. [naval.ts] */
  canBoat(p: PlayerId, targetTile: Tile): string | null;
  /** [nukes.ts] */
  nukeCost(p: PlayerId, kind: NukeKind): number;
  /** null = allowed, otherwise a short Italian reason. [nukes.ts] */
  canNuke(p: PlayerId, kind: NukeKind, targetTile: Tile): string | null;
  /** Blast radius in tiles. [nukes.ts] */
  nukeRadius(kind: NukeKind): number;
  /** AI attitude of `a` towards `b`, -100 (hates) .. +100 (loves). [diplomacy.ts] */
  relation(a: PlayerId, b: PlayerId): number;
}

export interface GameOptions {
  seed?: number;
  humanName?: string;
  /** Where the human spawns. null/undefined = no human (bots only / spectator). */
  humanSpawn?: { x: number; y: number } | null;
  /** 0xRRGGBB */
  humanColor?: number;
  /** Max nation bots (taken from map.nations by strength). Default 88. */
  nations?: number;
  /** Tribe bots (small, passive). Default 150. */
  tribes?: number;
  difficulty?: Difficulty;
}
